package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The rules a claim must keep to be added to a person (see AddClaim), checked without writing anything. */
public final class ClaimRules {

    private ClaimRules() {
    }

    /** The claim's date (the sheet's entry date, else its today, when none was given); a date inside a closed period or after the person's
     *  retirement date is refused, as is a negative amount that does not correct a SETTLED claim (see Corrections). */
    public static Checked check(Person person, ClaimValues values, SettingRepository settings, PeriodRepository periods,
            ClaimRepository claims) throws InvalidClaimException {
        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
        if (periods.closedOn(person.sheetId(), date)) {
            throw new InvalidClaimException("The claim's date is inside a closed period");
        }
        if (!person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        return new Checked(date, Corrections.check(person.sheetId(), person.id(), values, claims));
    }

    /** A claim's date and the number it corrects (null when none), once its rules are kept. */
    public record Checked(LocalDate date, String corrects) {
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim to the person; a claim given no date is dated the sheet's entry date, else its today. A claim dated inside a closed
 *  period, or after the person's retirement date, is refused, as is a
 *  negative amount that does not correct a SETTLED claim of the person (see Corrections). Its due-by is fixed here: its
 *  date plus the person's own terms, else the terms of their grade in force on that date. A claim dated inside a soft-closed period is
 *  marked a late entry. Its status log starts with its DRAFT line (see ClaimLog). */
public class AddClaim {
    public void add(@Val Person person, @Val ClaimValues values, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, ClaimLog log, Out<Claim> claim) throws InvalidClaimException {
        ClaimRules.Checked checked = ClaimRules.check(person, values, settings, periods, claims);
        LocalDate date = checked.date();
        Claim added = claims.add(person.sheetId(), person.id(), values.amount(), date, values.note(), checked.corrects(),
                date.plusDays(settings.terms(person.sheetId(), person.terms(), person.gradeOn(date), date)));
        log.write(added, values.by());
        if (periods.softClosedOn(added.sheetId(), date)) {
            claims.markLateEntry(added);
        }
        claim.set(added);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds the checked claims as DRAFTs in the order pasted, each as AddClaim adds one, writing CLAIM_ADDED for each (and LATE_ENTRY after it for a late entry) and
 *  then the figures the paste moved (see Rollup). */
public class AddPastedClaims {
    public void add(@PathVariable("sheetId") String sheetId, @Val PastedClaims checked, @Val PastedLines pasted,
            @Val RollupBefore before, ClaimRepository claims, SettingRepository settings, PeriodRepository periods, ClaimLog log, Rollup rollup,
            Audit audit, Out<PasteClaimsResult> result) {
        List<String> lines = new ArrayList<>();
        for (PastedClaim c : checked.claims()) {
            LocalDate date = c.checked().date();
            String sheet = c.person().sheetId();
            Claim added = claims.add(sheet, c.person().id(), c.values().amount(), date, c.values().note(),
                    c.checked().corrects(), date.plusDays(settings.terms(sheet, c.person().terms(), c.person().gradeOn(date), date)));
            log.write(added, pasted.by());
            lines.add("CLAIM_ADDED sheet=" + added.sheetId() + " by=" + pasted.by() + " person=" + c.person().name()
                    + " amount=" + added.amount().toPlainString() + " date=" + added.date());
            if (periods.softClosedOn(sheet, date)) {
                claims.markLateEntry(added);
                lines.add("LATE_ENTRY sheet=" + added.sheetId() + " by=" + pasted.by() + " person=" + c.person().name()
                        + " amount=" + added.amount().toPlainString() + " date=" + added.date());
            }
        }
        lines.forEach(audit::record);
        rollup.record(sheetId.trim(), pasted.by(), before);
        result.set(new PasteClaimsResult(checked.claims().size()));
    }
}
package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import org.springframework.web.bind.annotation.PathVariable;

/** The claim is dated the sheet's entry date, else its today, which may not be inside a closed period. Checked before a new person is
 *  added, so a refused claim leaves no person and no audit record behind. */
public class CheckQuickAddDate {
    public void check(@PathVariable("sheetId") String sheetId, SettingRepository settings, PeriodRepository periods)
            throws InvalidClaimException {
        String sheet = sheetId.trim();
        if (periods.closedOn(sheet, settings.claimDate(sheet))) {
            throw new InvalidClaimException("The claim's date is inside a closed period");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * The number a claim receives as it is opened. While the sheet's period-numbering-from setting is a date and the
 * sheet's today is on or after it, the claim is numbered within the period containing its date, {@code <period>-<n>}
 * counting from 1 in each period, or {@code X-<n>} in its own sequence when no period contains it. Otherwise it takes
 * the sheet-wide next number (1, 2, ...), which continues where it left off.
 */
public final class ClaimNumbering {

    private ClaimNumbering() {
    }

    public static String next(Claim claim, ClaimRepository claims, PeriodRepository periods, SettingRepository settings,
            SheetRepository sheets) {
        String sheet = claim.sheetId();
        if (!perPeriod(sheet, settings, sheets)) {
            return String.valueOf(claims.nextNumber(sheet));
        }
        Period period = periods.containing(sheet, claim.date());
        String key = period == null ? "X" : period.name();
        return key + "-" + claims.nextPeriodNumber(sheet, key);
    }

    /** Whether claims are numbered per period now: the period-numbering-from setting is a date on or before today. */
    public static boolean perPeriod(String sheet, SettingRepository settings, SheetRepository sheets) {
        LocalDate from = settings.periodNumberingFrom(sheet);
        return from != null && !sheets.today(sheet).isBefore(from);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The stored periods of each sheet. */
@Repository
public class PeriodRepository {

    private static final String COLUMNS = "id, sheet_id, name, from_date, to_date, closed, closed_total, soft_closed";

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public PeriodRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** A period as it stood at the end of a date: closed or soft-closed then, with the figures that fixed. */
    public record StateAsOf(boolean closed, boolean soft, BigDecimal closedTotal, Map<Long, BigDecimal> personTotals) {
    }

    /** The sheet's periods as they stood at the end of the date, by from-date, each with its state then: one added while
     *  the sheet's today was after it is left out; one never closed, soft-closed or reopened is as it is now. */
    public Map<Period, StateAsOf> listAsOf(String sheetId, LocalDate date) {
        Map<Long, LocalDate> added = new java.util.HashMap<>();
        jdbc.query("SELECT id, added_on FROM period WHERE sheet_id = ?",
                (ResultSet rs) -> {
                    added.put(rs.getLong("id"), rs.getObject("added_on", LocalDate.class));
                }, sheetId);
        Map<Long, StateAsOf> states = new java.util.HashMap<>();
        java.util.Set<Long> logged = new java.util.HashSet<>();
        jdbc.query("SELECT period_id, closed, soft_closed, closed_total, person_totals, made_on FROM period_log"
                + " WHERE sheet_id = ? ORDER BY id", (ResultSet rs) -> {
                    long id = rs.getLong("period_id");
                    logged.add(id);
                    if (!AsOf.counts(rs.getObject("made_on", LocalDate.class), date)) {
                        return;
                    }
                    BigDecimal total = rs.getBigDecimal("closed_total");
                    Map<Long, BigDecimal> totals = new LinkedHashMap<>();
                    String text = rs.getString("person_totals");
                    if (text != null && !text.isEmpty()) {
                        for (String part : text.split(";")) {
                            int at = part.indexOf('=');
                            totals.put(Long.parseLong(part.substring(0, at)), new BigDecimal(part.substring(at + 1)).setScale(2));
                        }
                    }
                    states.put(id, new StateAsOf(rs.getBoolean("closed"), rs.getBoolean("soft_closed"),
                            total == null ? null : total.setScale(2), totals));
                }, sheetId);
        Map<Period, StateAsOf> out = new LinkedHashMap<>();
        for (Period p : list(sheetId)) {
            if (!AsOf.counts(added.get(p.id()), date)) {
                continue;
            }
            StateAsOf state = states.get(p.id());
            if (state == null) {
                state = logged.contains(p.id()) ? new StateAsOf(false, false, null, Map.of())
                        : new StateAsOf(p.closed(), p.soft(), p.closedTotal(), p.closed() || p.soft() ? personTotals(p) : Map.of());
            }
            out.put(p, state);
        }
        return out;
    }

    /** Logs the period's new state with the sheet's today. */
    private void log(Period period, boolean closed, boolean soft, BigDecimal total) {
        jdbc.update("INSERT INTO period_log (sheet_id, period_id, closed, soft_closed, closed_total, made_on) VALUES (?, ?, ?, ?, ?, ?)",
                period.sheetId(), period.id(), closed, soft, total, Date.valueOf(sheets.today(period.sheetId())));
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? ORDER BY from_date, id",
                PeriodRepository::map, sheetId);
    }

    /** Whether the name is already a period's on the sheet, case and outer spaces ignored. */
    public boolean nameTaken(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND LOWER(name) = LOWER(?)",
                Integer.class, sheetId, name.trim());
        return n != null && n > 0;
    }

    /** Whether any period of the sheet shares a day with the dates from..to, both inclusive. */
    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, Date.valueOf(to), Date.valueOf(from));
        return n != null && n > 0;
    }

    /** A period of the sheet by id, or null when it has none. */
    public Period find(String sheetId, long id) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND id = ?",
                PeriodRepository::map, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The period of the sheet whose dates contain the date, or null when none does. */
    public Period containing(String sheetId, LocalDate date) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                PeriodRepository::map, sheetId, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether a closed period of the sheet contains the date. */
    public boolean closedOn(String sheetId, LocalDate date) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND closed = TRUE "
                + "AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Closes the period with its fixed due-total, but only while it is not closed (open or soft-closed), dropping the
 *  figures a soft close fixed; false when it was closed. */
    public boolean close(Period period, BigDecimal total) {
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_id = ?", period.sheetId(), period.id());
        boolean done = jdbc.update("UPDATE period SET closed = TRUE, soft_closed = FALSE, closed_total = ? WHERE sheet_id = ? AND id = ? AND closed = FALSE",
                total, period.sheetId(), period.id()) == 1;
        if (done) {
            log(period, true, false, total);
        }
        return done;
    }

    /** Soft-closes the period with its fixed due-total, but only while it is open; false when it was not. */
    public boolean softClose(Period period, BigDecimal total) {
        boolean done = jdbc.update("UPDATE period SET soft_closed = TRUE, closed_total = ? WHERE sheet_id = ? AND id = ? AND closed = FALSE "
                + "AND soft_closed = FALSE", total, period.sheetId(), period.id()) == 1;
        if (done) {
            log(period, false, true, total);
        }
        return done;
    }

    /** Whether a soft-closed period of the sheet contains the date. */
    public boolean softClosedOn(String sheetId, LocalDate date) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND soft_closed = TRUE "
                + "AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Fixes each person's due-total for the period, as it is closed (kept on its close's log line too). */
    public void fixPersonTotals(Period period, Map<Long, BigDecimal> totals) {
        StringBuilder text = new StringBuilder();
        for (Map.Entry<Long, BigDecimal> e : totals.entrySet()) {
            jdbc.update("INSERT INTO period_person_total (sheet_id, period_id, person_id, total) VALUES (?, ?, ?, ?)",
                    period.sheetId(), period.id(), e.getKey(), e.getValue());
            text.append(text.length() == 0 ? "" : ";").append(e.getKey()).append('=').append(e.getValue().toPlainString());
        }
        jdbc.update("UPDATE period_log SET person_totals = ? WHERE id = (SELECT MAX(id) FROM period_log WHERE sheet_id = ?"
                + " AND period_id = ?)", text.toString(), period.sheetId(), period.id());
    }

    /** The fixed due-total of each person for the closed period, by person id. */
    public Map<Long, BigDecimal> personTotals(Period period) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_id = ? ORDER BY person_id",
                (ResultSet rs) -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total").setScale(2));
                }, period.sheetId(), period.id());
        return totals;
    }

    /** Reopens the period, dropping its fixed due-totals, but only while it is closed or soft-closed; false when it was not. */
    public boolean reopen(Period period) {
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_id = ?", period.sheetId(), period.id());
        boolean done = jdbc.update("UPDATE period SET closed = FALSE, soft_closed = FALSE, closed_total = NULL WHERE sheet_id = ? AND id = ? "
                + "AND (closed = TRUE OR soft_closed = TRUE)",
                period.sheetId(), period.id()) == 1;
        if (done) {
            log(period, false, false, null);
        }
        return done;
    }

    /** Stores a new period and returns it with its id. */
    public Period add(String sheetId, String name, LocalDate from, LocalDate to) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update((con) -> {
            var ps = con.prepareStatement("INSERT INTO period (sheet_id, name, from_date, to_date, added_on) VALUES (?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setDate(3, Date.valueOf(from));
            ps.setDate(4, Date.valueOf(to));
            ps.setDate(5, Date.valueOf(sheets.today(sheetId)));
            return ps;
        }, keys);
        return new Period(keys.getKey().longValue(), sheetId, name, from, to, false, null, false);
    }

    private static Period map(ResultSet rs, int n) throws SQLException {
        BigDecimal total = rs.getBigDecimal("closed_total");
        return new Period(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                rs.getDate("from_date").toLocalDate(), rs.getDate("to_date").toLocalDate(), rs.getBoolean("closed"), total == null ? null : total.setScale(2),
                rs.getBoolean("soft_closed"));
    }
}
