package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Applies the edited values; only a DRAFT claim can be edited (an open claim is voided and a new one added instead),
 * and a claim dated inside a closed period, or moved into one, or left or moved after its person's retirement date, is refused. */
public class ApplyClaim {
    public void apply(@Val Claim claim, @Val ClaimValues values, SheetRepository sheets, PeriodRepository periods,
            PersonRepository people, ClaimRepository claims, Out<Claim> changed) throws InvalidClaimException {
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.sheetId());
        if (periods.closedOn(claim.sheetId(), claim.date()) || periods.closedOn(claim.sheetId(), date)) {
            throw new InvalidClaimException("The claim's date is inside a closed period");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person != null && !person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), values.amount(), date, values.note(), claim.status(),
                claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(),
                Corrections.check(claim.sheetId(), claim.personId(), values, claims), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Re-dates an OPEN or PENDING claim, by a steward. Its due-by stays as it was fixed and a figure a statement bound it
 * to stays bound; its period follows the new date. While per-period numbering is on (see ClaimNumbering) and the new
 * date falls in another period's sequence than the old one, the claim takes the next number of its new sequence (its
 * old number is never given again). Anyone but a steward, any other claim, a claim dated inside a closed period, a new
 * date inside one, or a new date after the person's retirement, is refused.
 */
public class ApplyRedate {
    public void apply(@Val Claim claim, @Val ClaimRedating request, RoleRepository roles, PersonRepository people,
            PeriodRepository periods, SettingRepository settings, SheetRepository sheets, ClaimRepository claims,
            Out<Claim> changed, Out<ClaimRedating> redating) throws InvalidClaimStatusException {
        String sheet = claim.sheetId();
        if (!RoleRepository.STEWARD.equals(roles.roleOf(sheet, request.by()))) {
            throw new InvalidClaimStatusException("Only a steward re-dates a claim");
        }
        if (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be re-dated");
        }
        if (periods.closedOn(sheet, claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
        }
        if (periods.closedOn(sheet, request.date())) {
            throw new InvalidClaimStatusException("The new date is inside a closed period");
        }
        Person person = people.find(sheet, claim.personId());
        if (person == null || !person.mayClaimOn(request.date())) {
            throw new InvalidClaimStatusException("The new date is after the person's retirement");
        }
        Claim redated = new Claim(claim.id(), sheet, claim.personId(), claim.amount(), request.date(), claim.note(),
                claim.status(), claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(),
                claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom());
        String number = claim.number();
        if (ClaimNumbering.perPeriod(sheet, settings, sheets)
                && !keyOf(periods.containing(sheet, claim.date())).equals(keyOf(periods.containing(sheet, request.date())))) {
            number = ClaimNumbering.next(redated, claims, periods, settings, sheets);
        }
        changed.set(new Claim(claim.id(), sheet, claim.personId(), claim.amount(), request.date(), claim.note(),
                claim.status(), number, claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(),
                claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom()));
        redating.set(new ClaimRedating(request.date(), request.by(), claim.date()));
    }

    private static String keyOf(Period period) {
        return period == null ? "X" : period.name();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Stores the claim's remaining amount, but only while it is still OPEN with the amount the split started from (a
 * change another user made first is refused), then adds the new claim: the split-off amount, the same person, date
 * and note, its due-by fixed now from the person's own terms, else those of their grade in force on its date, OPEN with the sheet's next
 * number (see ClaimNumbering), opened by the user who split, and the original's number as split-from. The new claim's
 * status log starts with its OPEN line (see ClaimLog).
 */
public class SaveSplit {
    public void save(@Val Claim claim, @Val ClaimSplit split, ClaimRepository claims, PersonRepository people,
            PeriodRepository periods, SettingRepository settings, SheetRepository sheets, ClaimLog log,
            Out<SplitOff> made) throws InvalidClaimStatusException {
        if (!claims.split(claim, claim.amount().add(split.amount()))) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        String grade = person == null ? null : person.gradeOn(claim.date());
        Claim added = claims.add(claim.sheetId(), claim.personId(), split.amount(), claim.date(), claim.note(), null,
                claim.date().plusDays(settings.terms(claim.sheetId(), person == null ? null : person.terms(), grade, claim.date())));
        String number = ClaimNumbering.next(added, claims, periods, settings, sheets);
        Claim opened = new Claim(added.id(), added.sheetId(), added.personId(), added.amount(), added.date(),
                added.note(), ClaimStatus.OPEN, number, null, split.by(), false, null, null, added.dueBy(), null, 0,
                claim.number());
        claims.updateStatus(opened, ClaimStatus.DRAFT);
        claims.splitFrom(opened);
        log.write(opened, split.by());
        made.set(new SplitOff(opened));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the split amount off the claim: it keeps the rest of its amount and loses any figure a statement bound it to.
 * Only an OPEN claim that is not deferred (see ClaimDue#deferred) nor dated inside a closed period is split, only by
 * an amount more than 0.00 and less than its amount, and only by a user whose role the sheet lets open a claim (the
 * new claim is theirs to open; see SettingRepository#permits).
 */
public class ApplySplit {
    public void apply(@Val Claim claim, @Val ClaimSplit split, SheetRepository sheets, PeriodRepository periods,
            SettingRepository settings, RoleRepository roles, Out<Claim> changed) throws InvalidClaimStatusException {
        if (claim.status() != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("Only an OPEN claim can be split");
        }
        if (ClaimDue.deferred(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("A deferred claim cannot be split");
        }
        if (periods.closedOn(claim.sheetId(), claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
        }
        if (split.amount().signum() <= 0 || split.amount().compareTo(claim.amount()) >= 0) {
            throw new InvalidClaimStatusException("A split takes more than 0.00 and less than the claim's amount");
        }
        String role = roles.roleOf(claim.sheetId(), split.by());
        if (!settings.permits(claim.sheetId(), "open", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not open a claim");
        }
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount().subtract(split.amount()),
                claim.date(), claim.note(), claim.status(), claim.number(), claim.due(), claim.openedBy(), false, null,
                claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom()));
    }
}

